@pytest.mark.parametrize('seq', ['ABC', [1, 2, 3]])
def test_every_split_is_covered(seq):
    # With a zero-width window the triples enumerate every split of seq.
    splits = {
        (prefix, suffix)
        for prefix, _window, suffix in windowed_complete(seq, 0)
    }
    expected = {
        (tuple(seq[:i]), tuple(seq[i:])) for i in range(len(seq) + 1)
    }
    assert splits == expected

    # For every window width, the window is contiguous and reconstructs seq.
    for n in range(len(seq) + 1):
        assert_valid_triples(list(windowed_complete(seq, n)), tuple(seq), n)
